import { existsSync } from 'node:fs';
import path from 'node:path';
import { besideTexts, collectClipTexts, GROUPS, unusedClips, type AudioManifest } from '../../scripts/generate-audio.ts';
import { clipKey, type RecordedManifest } from '../../src/audio/speech';
import { course } from '../../src/curriculum';
import { clipManifest } from '../../src/extension/clips';
import { contrasts } from '../../src/sounds/pairs';
import { wordThemes } from '../../src/words/content';

// The manifest is generated by `pnpm audio:generate`; until then there is nothing to check.
const manifest = Object.values(import.meta.glob<AudioManifest>('../../src/audio/clips.json', { eager: true, import: 'default' }))[0];
const recorded = Object.values(import.meta.glob<RecordedManifest>('../../src/audio/recorded.json', { eager: true, import: 'default' }))[0];
// Vitest runs from the repository root.
const publicDir = path.resolve('public');
/** Every lesson the extension plays: the course, then the pack scenes (as the script loads them). */
const played = [...course.lessons, ...course.packs.flatMap((pack) => pack.scenes)];

describe.skipIf(!manifest)('the generated audio manifest', () => {
  const clips = manifest?.clips ?? {};
  const clipsB = manifest?.clipsB ?? {};

  it('names both voices and the model it was made with', () => {
    expect(manifest?.voices.a.id).toBeTruthy();
    expect(manifest?.voices.b.id).toBeTruthy();
    expect(manifest?.voices.a.id).not.toBe(manifest?.voices.b.id);
    expect(manifest?.model).toMatch(/^eleven_/);
  });

  it('points every clip at an mp3 that exists in public/', () => {
    const files = [...Object.values(clips), ...Object.values(clipsB)];
    expect(files.length).toBeGreaterThan(0);
    expect(files.filter((file) => !/^audio\/[0-9a-f]{16}\.mp3$/.test(file))).toEqual([]);
    expect(files.filter((file) => !existsSync(path.join(publicDir, file)))).toEqual([]);
  });

  it('keys clips the way the speaker looks them up', () => {
    const keys = [...Object.keys(clips), ...Object.keys(clipsB)];
    expect(keys.filter((key) => key !== clipKey(key))).toEqual([]);
  });

  it('has no stale entries: every key is a text the course plays in that voice', () => {
    const texts = collectClipTexts(played, besideTexts(wordThemes, contrasts));
    const voiceA = new Set(texts.filter((text) => text.voice === 'a').map((text) => text.text));
    const voiceB = new Set(texts.filter((text) => text.voice === 'b').map((text) => text.text));
    expect(Object.keys(clips).filter((key) => !voiceA.has(key))).toEqual([]);
    expect(Object.keys(clipsB).filter((key) => !voiceB.has(key))).toEqual([]);
  });
});

describe('the human takes manifest', () => {
  const takes = recorded?.takes ?? {};

  it('is there for the extension to bundle before any recording, and reaches the speaker', () => {
    expect(recorded).toEqual({ takes: expect.any(Object) });
    expect(clipManifest.recorded).toEqual(takes);
  });

  it('points every take at a processed mp3 in public/audio/recorded/', () => {
    const files = Object.values(takes).flat();
    expect(files.filter((file) => !/^audio\/recorded\/[a-z0-9-]+\/[a-z0-9-]+\.mp3$/.test(file))).toEqual([]);
    expect(files.filter((file) => !existsSync(path.join(publicDir, file)))).toEqual([]);
  });

  it('keys takes by texts the course plays', () => {
    const texts = new Set(collectClipTexts(played, besideTexts(wordThemes, contrasts)).map((text) => text.text));
    expect(Object.keys(takes).filter((key) => !texts.has(key))).toEqual([]);
  });

  it('is out of reach of --prune, which only looks at files directly in public/audio/', () => {
    const entry = (name: string, file = true) => ({ name, isFile: () => file });
    expect(unusedClips([entry('a.mp3'), entry('b.mp3'), entry('recorded', false), entry('notes.txt')], new Set(['a.mp3']))).toEqual(['b.mp3']);
  });
});

describe('collecting the texts to voice', () => {
  const beside = besideTexts(wordThemes, contrasts);

  it('voices the basic words and the minimal pairs right after the lesson items', () => {
    expect(GROUPS.slice(0, 4)).toEqual(['target', 'items', 'words', 'pairs']);
    expect(beside.words).toContain('de vork');
    expect(beside.pairs).toEqual(expect.arrayContaining(['man', 'maan', 'goed', 'hoed']));
  });

  it('keeps a text in its first group only, so a word the course teaches stays a lesson item', () => {
    const texts = collectClipTexts(course.lessons, { words: ['de keuken', 'de vork'], pairs: ['de vork', 'man'] });
    expect(texts.filter((text) => text.text === clipKey('de keuken')).map((text) => text.group)).toEqual(['items']);
    expect(texts.filter((text) => text.text === clipKey('de vork')).map((text) => text.group)).toEqual(['words']);
    expect(texts.find((text) => text.text === clipKey('man'))?.group).toBe('pairs');
  });

  it('leaves the word track’s references to the course out of the words group', () => {
    const refs = wordThemes.flatMap((theme) => theme.words.flatMap((entry) => ('ref' in entry ? [entry.ref] : [])));
    expect(refs.length).toBeGreaterThan(0);
    expect(beside.words.filter((word) => refs.includes(word))).toEqual([]);
  });
});
